require "rails_helper"

RSpec.describe "Seed refusal once a Timekeeping handoff has begun" do
  # "A missing ownership row counts as begun."
  it "timesheet_data refuses with no ownership row, writes no company and leaves the ownership table empty" do
    allow($stdout).to receive(:write)
    TimekeepingOwnership.delete_all
    company_baseline = Company.count

    expect { load Rails.root.join("db/seeds/timesheet_data.rb") }
      .to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(Company.count).to eq(company_baseline)
    expect(Company.exists?(name: "Test Company")).to be(false)
    expect(TimekeepingOwnership.count).to eq(0)
  end
end

RSpec.describe "Seed refusal once a Timekeeping handoff has begun" do
  # "`db/seeds.rb`: refuse right after `TimekeepingOwnership.ensure_initial!` (line 155) and before the company update."
  it "db/seeds.rb refuses while a handoff step is set, leaves the existing company unchanged and keeps the begun ownership row" do
    allow($stdout).to receive(:write)
    company = create(:company, name: "Fork & Leaf Salads", business_phone: "+1 2025550123")
    TimekeepingOwnership.current.update_columns(generation: 1, handoff_step: "close_admission", owner: "monolith", monolith_store: "legacy")
    baseline = company.reload.attributes
    expect(company.reload.attributes).to eq(baseline)

    expect { load Rails.root.join("db/seeds.rb") }
      .to raise_error(TimekeepingOwnership::HandoffBegun)

    expect(company.reload.attributes).to eq(baseline)
    expect(TimekeepingOwnership.pluck(:generation, :handoff_step, :owner, :monolith_store))
      .to eq([[1, "close_admission", "monolith", "legacy"]])
  end
end
